labels=['Source hypotheses','Constructed objects','Domain and index coverage','Transition and comparison maps','Identity of consumed object','Coefficient and normalization conventions','Local conditions','Exceptional cases','Downstream consumption']
def row(n,req,built,match,ev,status='incomplete_review'):
 return dict(obligation=labels[n-1],required=req,constructed_or_proved=built,why_match_or_remaining=match,evidence=ev,status=status)
def app(id,claim,source,construction,application,consumer,rows):
 return dict(id=id,claim=claim,decision='incomplete_review',source_ids=source,construction=construction,application=application,consumers=consumer,obligations=rows)
